using CleanHome.ServiceDefaults;
namespace CleanHome.Staff.Api.Repositories;
public sealed class AssignmentLifecycleRepository(DatabaseConnectionFactory connections){
 public async Task<object> Requests(long? user,long? booking,string? state,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT w.id,w.assignment_id,a.booking_id,a.employee_id,w.requested_by,w.reason,w.state,w.requested_at,w.reviewed_by,w.reviewed_at,w.review_note FROM assignment_withdrawals w JOIN assignments a ON a.id=w.assignment_id JOIN employees e ON e.id=a.employee_id WHERE (@user IS NULL OR e.user_id=@user) AND (@booking IS NULL OR a.booking_id=@booking) AND (@state IS NULL OR w.state=@state) ORDER BY w.id DESC LIMIT 200",("user",user),("booking",booking),("state",state));return await q.RowsAsync(ct);}
 public async Task<object> History(long? user,long? booking,CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT x.id,x.assignment_id,a.booking_id,a.employee_id,x.source,x.reason,x.created_at FROM assignment_exits x JOIN assignments a ON a.id=x.assignment_id JOIN employees e ON e.id=a.employee_id WHERE (@user IS NULL OR e.user_id=@user) AND (@booking IS NULL OR a.booking_id=@booking) ORDER BY x.id DESC LIMIT 200",("user",user),("booking",booking));return await q.RowsAsync(ct);}
 public async Task<int> Policy(CancellationToken ct){await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("SELECT early_minutes FROM withdrawal_policy WHERE id=1");return Convert.ToInt32(await q.ExecuteScalarAsync(ct));}
 public async Task SavePolicy(int minutes,CancellationToken ct){if(minutes is <0 or >10080)throw new ApiException(400,"Ngưỡng hủy trực tiếp từ 0 đến 10080 phút.");await using var c=await connections.OpenAsync(ct);await using var q=c.Sql("UPDATE withdrawal_policy SET early_minutes=@minutes WHERE id=1",("minutes",minutes));await q.ExecuteNonQueryAsync(ct);}
}
